function formatAssetName(e){return(e.substring(0,e.lastIndexOf("."))||e).split(/[-_]/).map(e=>{const n=e.toLowerCase();return"ssh"===n||"ss"===n?"SS":"rx"===n?"Rx":e.charAt(0).toUpperCase()+e.slice(1)}).join(" ")}function getAssetMeta(e){const n=e.split(".").pop().toLowerCase();return"svg"===n?"Vector SVG · Scalable Resolution":"png"===n?"PNG Image · High Definition":"jpg"===n||"jpeg"===n?"JPEG Image · Compressed Layout":"Asset File"}function getTagClass(e){const n=e.toLowerCase();return n.includes("clinic")?"tag-clinic":n.includes("wellness")||n.includes("supplement")?"tag-wellness":n.includes("ecom")||n.includes("groom")?"tag-ecom":"tag-ss"}function getTagIcon(e){const n=e.toLowerCase();return n.includes("clinic")?'<iconify-icon icon="fluent:stethoscope-24-regular" class="me-1"></iconify-icon>':n.includes("wellness")||n.includes("supplement")?'<iconify-icon icon="fluent:pill-24-regular" class="me-1"></iconify-icon>':n.includes("ecom")||n.includes("groom")?'<iconify-icon icon="fluent:shopping-bag-24-regular" class="me-1"></iconify-icon>':'<iconify-icon icon="fluent:organization-24-regular" class="me-1"></iconify-icon>'}